"""Pure wheredirs resolver implementing the pinned v0.1.0 contract."""

import os as _os
import re as _re
import sys as _sys
import warnings as _warnings
from collections.abc import Mapping as _Mapping

__all__ = [
    "config_dir", "data_dir", "cache_dir", "state_dir", "logs_dir",
    "runtime_dir", "which_strategy",
]
_ASCII_SPACE = " \t\n\r\f\v"
_PLATFORMS = {
    **dict.fromkeys(("linux", "freebsd", "openbsd", "netbsd", "dragonfly"), "xdg"),
    **dict.fromkeys(("macos", "darwin"), "apple"),
    **dict.fromkeys(("windows", "win32"), "windows"),
}
_STRATEGIES = ("xdg", "apple", "windows", "single-folder")


def which_strategy(platform: str) -> str:
    if not isinstance(platform, str) or platform not in _PLATFORMS:
        raise ValueError(f"Unrecognised platform: {platform!r}")
    return _PLATFORMS[platform]


def _join(base: str, *parts: str) -> str:
    # Strip separators only, preserving whitespace and relative bases.
    return base.replace("\\", "/").rstrip("/") + "/" + "/".join(parts)


def _home(env: _Mapping[str, str]) -> str:
    home = env.get("HOME")
    if not home:
        raise ValueError("HOME is required")
    return home


def _resolve(platform, env, function_name, args) -> str | None:
    """Resolve from explicit inputs; never consult ambient env/platform here.

    Directory args is a map containing app, optional author and strategy.
    The harness calls which_strategy directly with its single list argument.
    """
    if function_name not in __all__[:-1]:
        raise ValueError(f"Unknown directory function: {function_name!r}")
    if set(args) - {"app", "author", "strategy"}:
        raise ValueError("Unexpected resolver argument")
    app = args.get("app")
    # Validation precedes even the first environment lookup.
    if (not isinstance(app, str) or not app.strip(_ASCII_SPACE)
            or any(char in app for char in ("/", "\\", "\0"))
            or app.startswith(".") or app.endswith(".")):
        raise ValueError("Invalid app name")
    strategy = args.get("strategy")
    if strategy is None:
        strategy = which_strategy(platform)
    if strategy not in _STRATEGIES:
        raise ValueError(f"Unknown strategy: {strategy!r}")
    kind = function_name.removesuffix("_dir")
    author = args.get("author")

    if strategy == "single-folder":
        name = _re.sub(r"[ \t\n\r\f\v]+", "-", app.strip(_ASCII_SPACE))
        name = name.translate(str.maketrans("ABCDEFGHIJKLMNOPQRSTUVWXYZ", "abcdefghijklmnopqrstuvwxyz"))
        return _join(_home(env), "." + name)

    if strategy == "xdg":
        home = _home(env)
        if kind == "runtime":
            runtime = env.get("XDG_RUNTIME_DIR", "")
            if runtime.startswith("/"):
                return _join(runtime, app)
            _warnings.warn(
                "XDG_RUNTIME_DIR is unset, empty, or non-absolute; using cache_dir. "
                "This fallback has no runtime directory permission or lifetime guarantees.",
                RuntimeWarning, stacklevel=2,
            )
            return _resolve(platform, env, "cache_dir", args)
        variable, default = {
            "config": ("XDG_CONFIG_HOME", ".config"),
            "data": ("XDG_DATA_HOME", ".local/share"),
            "cache": ("XDG_CACHE_HOME", ".cache"),
            "state": ("XDG_STATE_HOME", ".local/state"),
            "logs": ("XDG_STATE_HOME", ".local/state"),
        }[kind]
        base = env.get(variable, "")
        if not base.startswith("/"):
            base = _join(home, default)
        return _join(base, app, "logs") if kind == "logs" else _join(base, app)

    if kind in ("state", "runtime"):
        return None
    if strategy == "apple":
        segment = f"{author}.{app}" if author else app
        base = {"config": "Application Support", "data": "Application Support",
                "cache": "Caches", "logs": "Logs"}[kind]
        return _join(_home(env), "Library", base, segment)

    base = env.get("LOCALAPPDATA")
    if not base:
        profile = env.get("USERPROFILE") or env.get("HOME")
        if not profile:
            raise ValueError("LOCALAPPDATA, USERPROFILE, and HOME are unset or empty")
        base = _join(profile, "AppData", "Local")
    parts = [author, app] if author else [app]
    if kind in ("cache", "logs"):
        parts.append({"cache": "Cache", "logs": "Logs"}[kind])
    return _join(base, *parts)


def config_dir(app: str, author: str | None = None, *, strategy: str | None = None) -> str | None:
    return _resolve(_sys.platform, _os.environ, "config_dir", dict(app=app, author=author, strategy=strategy))


def data_dir(app: str, author: str | None = None, *, strategy: str | None = None) -> str | None:
    return _resolve(_sys.platform, _os.environ, "data_dir", dict(app=app, author=author, strategy=strategy))


def cache_dir(app: str, author: str | None = None, *, strategy: str | None = None) -> str | None:
    return _resolve(_sys.platform, _os.environ, "cache_dir", dict(app=app, author=author, strategy=strategy))


def state_dir(app: str, author: str | None = None, *, strategy: str | None = None) -> str | None:
    return _resolve(_sys.platform, _os.environ, "state_dir", dict(app=app, author=author, strategy=strategy))


def logs_dir(app: str, author: str | None = None, *, strategy: str | None = None) -> str | None:
    return _resolve(_sys.platform, _os.environ, "logs_dir", dict(app=app, author=author, strategy=strategy))


def runtime_dir(app: str, author: str | None = None, *, strategy: str | None = None) -> str | None:
    return _resolve(_sys.platform, _os.environ, "runtime_dir", dict(app=app, author=author, strategy=strategy))

"""Run all wheredirs fixtures through the INSTALL internal API profile.

Exit 0 only for a nonempty, completely supported, passing suite. All report
paths must be beneath consumer/; fixture and implementation inputs are read-only.
"""
import argparse
from collections import Counter
from datetime import datetime, timezone
import hashlib
import importlib.util
import json
from pathlib import Path
import re
import sys
import warnings

import yaml

HERE = Path(__file__).resolve().parent
GROUPS = {"which_strategy", "xdg", "apple", "windows", "single-folder", "errors", "project"}
DIRECTORIES = {"config_dir", "data_dir", "cache_dir", "state_dir", "logs_dir", "runtime_dir"}
FIELDS = {"name", "function", "args", "description", "strategy", "platform", "env", "output", "raises"}
PLATFORMS = {**dict.fromkeys(("linux", "freebsd", "openbsd", "netbsd", "dragonfly"), "xdg"),
             **dict.fromkeys(("macos", "darwin"), "apple"),
             **dict.fromkeys(("windows", "win32"), "windows")}


def digest(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def normalize(value):
    return re.sub(r"/+", "/", value.replace("\\", "/")).rstrip("/")


def substitute(output, env):
    # Match full variable tokens: undeclared names remain literal. Build the
    # declared alternatives longest-first, without recursive substitution.
    names = sorted(env, key=lambda name: (-len(name), name))
    if not names:
        return output
    pattern = r"\$(?:" + "|".join(re.escape(name) for name in names) + r")(?![A-Za-z0-9_])"
    return re.sub(pattern, lambda match: env[match.group()[1:]], output)


def requirements(group, case):
    problems = []
    if group not in GROUPS:
        problems.append(f"Unknown group {group!r}")
    if not isinstance(case, dict):
        return problems + ["Case must be a mapping"]
    problems += [f"Unsupported field {field!r}" for field in sorted(set(case) - FIELDS)]
    for field in ("name", "function", "args"):
        if field not in case:
            problems.append(f"Missing {field}")
    if not isinstance(case.get("name"), str) or not case.get("name"):
        problems.append("Case name must be a nonempty string")
    if "description" in case and not isinstance(case["description"], str):
        problems.append("description must be a string")
    if "raises" in case and type(case["raises"]) is not bool:
        problems.append("raises must be boolean")
    if case.get("raises") is True:
        if "output" in case:
            problems.append("Error expectation cannot also declare output")
    elif "output" not in case or (case["output"] is not None and not isinstance(case["output"], str)):
        problems.append("Return expectation must be string or null")
    function = case.get("function")
    args = case.get("args")
    if function == "which_strategy":
        if not isinstance(args, list) or len(args) != 1:
            problems.append("which_strategy requires a one-element args list")
        if set(case) & {"platform", "env", "strategy"}:
            problems.append("which_strategy has no env/platform/strategy inputs")
    elif function in DIRECTORIES:
        if not isinstance(args, dict) or "app" not in args or set(args) - {"app", "author"}:
            problems.append("Directory args requires app and optional author only")
        if not {"platform", "env", "strategy"}.issubset(case):
            problems.append("Directory case requires pinned platform/env/strategy")
        env = case.get("env")
        if not isinstance(env, dict) or any(not isinstance(k, str) or not isinstance(v, str) for k, v in env.items()):
            problems.append("env must map strings to strings")
    else:
        problems.append(f"Unsupported function {function!r}")
    return problems


def evaluate(module, group, index, case, duplicate_names):
    name = case.get("name", f"{group}/{index}") if isinstance(case, dict) else f"{group}/{index}"
    result = {"name": name, "group": group, "index": index, "status": "unsupported",
              "assertions": [], "warnings": [], "reasons": []}
    problems = requirements(group, case)
    if name in duplicate_names:
        problems.append("Duplicate case ID")
    if problems:
        result["reasons"] = problems
        return result
    function = case["function"]
    actual = None
    error = None
    with warnings.catch_warnings(record=True) as observed:
        warnings.simplefilter("always")
        try:
            if function == "which_strategy":
                actual = module.which_strategy(case["args"][0])
            else:
                args = {**case["args"], "strategy": case["strategy"]}
                actual = module._resolve(case["platform"], dict(case["env"]), function, args)
        except Exception as exc:
            error = {"type": type(exc).__name__, "message": str(exc)}
    result["warnings"] = [{"category": w.category.__name__, "message": str(w.message),
                            "filename": w.filename, "lineno": w.lineno} for w in observed]
    result["actual"] = actual if actual is None or isinstance(actual, (str, bool, int, float)) else repr(actual)
    result["error"] = error
    if case.get("raises") is True:
        assertion = {"kind": "raises", "expected": "an exception", "actual": error or actual,
                     "passed": error is not None, "stage": "invocation"}
    else:
        expected = case["output"]
        if isinstance(expected, str):
            expected = normalize(substitute(expected, case.get("env", {})))
            comparison = normalize(actual) if isinstance(actual, str) else actual
            passed = error is None and isinstance(actual, str) and expected == comparison
        else:
            comparison = actual
            passed = error is None and actual is None
        assertion = {"kind": "null" if expected is None else "return", "expected": expected,
                     "actual": comparison if error is None else error, "passed": passed,
                     "stage": "invocation" if error else "comparison"}
    result["assertions"].append(assertion)
    # Warnings are required by SPEC/INSTALL, although YAML has no warning field.
    # Observe every call; successful XDG runtime fallback must emit a warning.
    # For other cases this remains evidence, without imposing unspecified rules
    # on warning counts, categories, messages, or errors preceding the fallback.
    if function == "runtime_dir" and not case.get("raises"):
        strategy = case["strategy"] or PLATFORMS.get(case["platform"])
        runtime = case["env"].get("XDG_RUNTIME_DIR", "")
        if strategy == "xdg" and not runtime.startswith("/"):
            result["assertions"].append({"kind": "runtime_fallback_warning", "expected": "at least one warning",
                                         "actual": len(observed), "passed": bool(observed), "stage": "warning"})
    result["status"] = "passed" if all(a["passed"] for a in result["assertions"]) else "failed"
    return result


def run(options):
    fixture = options.fixtures.resolve()
    implementation = options.implementation.resolve()
    document = yaml.safe_load(fixture.read_text())
    if not isinstance(document, dict):
        raise ValueError("Fixture root must be a mapping")
    records = []
    suite_errors = []
    if document.get("version") != "0.1.0":
        suite_errors.append("Missing or incompatible fixture version")
    for group, value in document.items():
        if group == "version":
            continue
        if not isinstance(value, list):
            suite_errors.append(f"Non-list case container: {group}")
            continue
        records.extend((group, index, case) for index, case in enumerate(value))
    names = [c.get("name") for _, _, c in records if isinstance(c, dict) and isinstance(c.get("name"), str)]
    duplicates = {name for name, count in Counter(names).items() if count > 1}
    inventory = json.loads(options.inventory.read_text())
    actual_ids = [(g, i, c.get("name") if isinstance(c, dict) else None) for g, i, c in records]
    inventory_ids = [(c["group"], c["index"], c["name"]) for c in inventory["cases"]]
    if actual_ids != inventory_ids:
        suite_errors.append("Runner discovered IDs differ from independent inventory")
    spec = importlib.util.spec_from_file_location("verified_wheredirs", implementation)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    for name in DIRECTORIES | {"which_strategy", "_resolve"}:
        if not callable(getattr(module, name, None)):
            raise ValueError(f"Implementation missing callable {name}")
    cases = [evaluate(module, g, i, c, duplicates) for g, i, c in records]
    statuses = Counter(c["status"] for c in cases)
    totals = {"discovered": len(cases), "executed": statuses["passed"] + statuses["failed"],
              **{k: statuses[k] for k in ("passed", "failed", "skipped", "unsupported")}}
    assertions = [a for c in cases for a in c["assertions"]]
    report = {"complete": not suite_errors and totals["discovered"] == inventory["discovered"],
              "conforms": bool(cases) and not suite_errors and statuses["passed"] == len(cases),
              "timestamp_utc": datetime.now(timezone.utc).isoformat(),
              "command": [sys.executable, *sys.argv], "scope": "all seven fixture groups; pinned-input Python resolver",
              "source": inventory["source"], "identity": {
                  "fixtures": {"path": str(fixture), "sha256": digest(fixture)},
                  "implementation": {"path": str(implementation), "sha256": digest(implementation)},
                  "runner": {"path": str(Path(__file__).resolve()), "sha256": digest(__file__)},
                  "inventory": {"path": str(options.inventory.resolve()), "sha256": digest(options.inventory)}},
              "environment": {"python": sys.version, "executable": sys.executable,
                              "sys_platform": sys.platform, "pyyaml": yaml.__version__,
                              "input_isolation": "explicit case dict; no os.environ mutation or reads by runner"},
              "totals": totals, "groups": {g: dict(Counter(c["status"] for c in cases if c["group"] == g))
                                           for g in document if g != "version"},
              "assertion_totals": {"attempted": len(assertions), "passed": sum(a["passed"] for a in assertions),
                                   "failed": sum(not a["passed"] for a in assertions),
                                   "by_kind": dict(Counter(a["kind"] for a in assertions))},
              "suite_errors": suite_errors, "cases": cases}
    for c in cases:
        if c["status"] != "passed":
            failed = [a for a in c["assertions"] if not a["passed"]]
            print(f"FAIL {c['name']}: {json.dumps(failed or c['reasons'], ensure_ascii=False)}")
    for error in suite_errors:
        print(f"SUITE FAIL: {error}")
    print(f"passed {totals['passed']} / total {totals['discovered']}")
    return report


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--fixtures", type=Path, default=HERE.parent / "contract/tests.yaml")
    parser.add_argument("--implementation", type=Path, default=HERE / "wheredirs.py")
    parser.add_argument("--inventory", type=Path, default=HERE / "inventory.json")
    parser.add_argument("--report", type=Path, default=HERE / "results.json")
    options = parser.parse_args()
    report_path = options.report.resolve()
    if not report_path.is_relative_to(HERE):
        parser.error("Report artifacts must be under consumer/")
    try:
        report = run(options)
    except Exception as exc:
        report = {"complete": False, "conforms": False, "stage": "setup",
                  "error": {"type": type(exc).__name__, "message": str(exc)},
                  "command": [sys.executable, *sys.argv]}
        print(f"SETUP FAIL: {exc}")
    report_path.parent.mkdir(parents=True, exist_ok=True)
    report_path.write_text(json.dumps(report, indent=2, ensure_ascii=False) + "\n")
    return 0 if report["conforms"] else 1


if __name__ == "__main__":
    sys.exit(main())
